  function friendly(value){return String(value||"").replace(/([a-z0-9])([A-Z])/g,"$1 $2").split(/[._\-/\s]+/).filter(Boolean).map(word=>{const lower=word.toLowerCase();if(WORD_LABELS[lower])return WORD_LABELS[lower];if(lower==="max")return"Maximum";if(lower==="min")return"Minimum";if(lower==="num")return"Number of";if(lower==="auto")return"Automatic";if(lower==="autostart")return"Automatic start";if(lower==="autoclose")return"Automatic close";if(lower==="passthrough")return"Passed through";if(lower==="oneshot")return"One-time";return lower.charAt(0).toUpperCase()+lower.slice(1)}).join(" ")}
