  function settingLabel(path){if(SETTING_LABELS[path])return SETTING_LABELS[path];const parts=String(path).split("."),leaf=parts.at(-1)||"",parent=parts.at(-2)||parts[0]||"setting",generic=/^(?:enabled|mode|backend|model|provider|endpoint|port|path|url|account|timeout|retries|interval|strategy|engine|transport|placement|region|name|max|min|maximum|minimum)$/i.test(withoutUnit(leaf));if(/^enabled$/i.test(leaf))return friendly(parent);const base=friendly(withoutUnit(leaf));return generic&&parts.length>1?`${friendly(parent)} ${base}`:base}
