  function renderProfileIdentity(){const profile=selectedProfile();if(!profile)return;$("identity-display-name").textContent=profileLabel(profile);$("profile-description").value=profile.description||"";const facts=$("profile-facts");facts.replaceChildren(fact("Profile ID",profileName(profile)),fact("Bot title",profile.bot_title||"Not set"),fact("Gateway",profile.gateway_running?"Running":"Not running"),fact("Skills",Number.isFinite(Number(profile.skill_count))?String(profile.skill_count):"Not reported"),fact("Environment",profile.has_env?"Configured":"No profile .env"),fact("Distribution",[profile.distribution_name,profile.distribution_version].filter(Boolean).join(" ")||"Standard Hermes"));$("profile-model-label").textContent=profile.model||"Not assigned";$("profile-provider-label").textContent=profile.provider?`Provider: ${profile.provider}`:"Provider not reported";$("open-delete-profile").disabled=Boolean(profile.is_default||profileName(profile)==="default");$("open-delete-profile").title=$("open-delete-profile").disabled?"The built-in default profile cannot be deleted":"Delete profile"}
